import io
import unittest
from unittest.mock import patch
class TestGeneratePassword(unittest.TestCase):
    @patch('os.urandom')
    def test_generate_password(self, mock_urandom):
        mock_urandom.return_value = b'0123456789abcdef'
        self.assertEqual(generate_password(2), 'abababab')

if __name__ == '__main__':
    unittest.main()
